export function calcularFrete(cep: string, pesoG: number, subtotal: number) {
  if (!/^\d{8}$/.test(cep)) throw new Error('CEP inválido');
  if (subtotal >= 30000) return 0;
  return pesoG <= 1000 ? 1500 : 1500 + Math.ceil((pesoG - 1000) / 500) * 400;
}

